'use strict';
const $=id=>document.getElementById(id);
let tasks=[],archiveChoices=[],csrf='',editing=null,view='list',writeAttempt=null,mutationPending=false;
const local=at=>new Date(at*1000+8*3600000).toISOString().slice(0,16);
const uid=()=>'web-'+crypto.randomUUID();
async function api(path,body){const r=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(body)}:{});const data=await r.json();if(!r.ok)throw Error(data.error||'请求失败');return data;}
async function refresh(){const data=await api('api/tasks');tasks=data.tasks;$('planSummary').textContent=tasks.filter(t=>t.status==='pending').length+' 项待完成';$('today').textContent=data.local_date.replaceAll('-','.');if(!$('day').value)$('day').value=data.local_date;render();}
function prepareAttempt(payload,key=JSON.stringify(payload)){if(!writeAttempt||writeAttempt.key!==key)writeAttempt={key,payload:{...payload,request_id:uid()}};return writeAttempt;}
async function submitAttempt(attempt){const result=await api('api/command',attempt.payload);if(writeAttempt===attempt)writeAttempt=null;return result;}
function element(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function render(){const root=$('tasks');root.replaceChildren();let shown=tasks.filter(t=>$('status').value==='all'||t.status===$('status').value);const query=$('search').value.trim().toLocaleLowerCase();if(query)shown=shown.filter(t=>(t.title+' '+t.body).toLocaleLowerCase().includes(query));if(view==='day')shown=shown.filter(t=>(t.start_at||t.due_at||t.remind_at)&&onDay(t,$('day').value));$('listCount').textContent=shown.length+' 项';if(!shown.length)root.append(element('div',view==='day'?'这一天，留一点空白也很好。':'还没有计划。把想做的事记下来吧。','empty'));for(const t of shown){const row=element('article',undefined,'task');const content=element('div',undefined,'task-content');content.append(element('h3',t.title));const meta=element('div',undefined,'meta');meta.append(element('span',({task:'待办',event:'日程',note:'便笺'})[t.kind]));meta.append(element('span',(t.start_at||t.due_at||t.remind_at)?local(t.start_at||t.due_at||t.remind_at).replace('T',' ')+' 北京时间':'未设置时间'));if(t.repeat!=='none')meta.append(element('span',t.repeat==='daily'?'每天重复':'每周重复'));if(t.remind)meta.append(element('span','提醒'));content.append(meta);if(t.start_at)meta.append(element('span','开始 '+local(t.start_at).replace('T',' ')));if(t.end_at)meta.append(element('span','结束 '+local(t.end_at).replace('T',' ')));if(t.remind_at&&t.remind&&(t.start_at||t.due_at))meta.append(element('span','提醒 '+local(t.remind_at).replace('T',' ')));if(t.body)content.append(element('p',t.body));row.append(content);const actions=element('div',undefined,'actions');const edit=element('button','编辑','quiet');edit.onclick=()=>open(t);actions.append(edit);if(t.status==='pending'){for(const [op,label]of [['complete',t.repeat==='none'?'完成':(view==='day'?'完成'+$('day').value+'本次':'选择本次完成日期')],['cancel',t.repeat==='none'?'取消':'结束系列']]){const b=element('button',label,op==='cancel'?'quiet':'');b.disabled=mutationPending;b.onclick=()=>mutate(op,t);actions.append(b);}}else actions.append(element('span',t.status==='completed'?'已完成':'已取消','muted'));row.append(actions);root.append(row);}}
function onDay(t,day){const base=local(t.start_at||t.due_at||t.remind_at).slice(0,10);if(base===day)return true;if(day<base||t.repeat==='none')return false;return t.repeat==='daily'||(Date.parse(day+'T00:00:00Z')-Date.parse(base+'T00:00:00Z'))/86400000%7===0;}
function renderArchiveLinks(ids=[]){const selected=new Set(ids);const choices=new Map(archiveChoices.map(record=>[record.id,record]));for(const id of selected)if(!choices.has(id))choices.set(id,{id,title:id});$('archive-links').replaceChildren();for(const record of choices.values()){const option=element('option',record.title+' · '+record.id);option.value=record.id;option.selected=selected.has(record.id);$('archive-links').append(option);}}
async function open(t=null){writeAttempt=null;editing=t;$('form-title').textContent=t?'编辑计划':'新建计划';$('title').value=t?.title||'';$('body').value=t?.body||'';$('kind').value=t?.kind||'task';$('repeat').value=t?.repeat||'none';$('due').value=t?.due_at?local(t.due_at):'';$('start').value=t?.start_at?local(t.start_at):'';$('end').value=t?.end_at?local(t.end_at):'';$('remind-at').value=t?.remind_at?local(t.remind_at):'';$('remind').checked=t?.remind||false;$('form-error').textContent='';renderArchiveLinks(t?.archive_links||[]);$('editor').showModal();try{archiveChoices=(await api('api/archive-choices')).records;if(editing===t)renderArchiveLinks(t?.archive_links||[]);}catch(e){$('form-error').textContent='暂时无法读取档案列表：'+e.message;}}
async function mutate(op,t){if(mutationPending)return;mutationPending=true;render();try{const chosen=view==='day'?$('day').value:null;const key=JSON.stringify({op,task_id:t.id,expected_revision:t.revision,chosen_date:chosen});let attempt=writeAttempt?.key===key?writeAttempt:null;if(!attempt){const value={op,task_id:t.id,expected_revision:t.revision};if(op==='complete'&&t.repeat!=='none'){const delivery=await api('api/delivery?task_id='+encodeURIComponent(t.id)+(chosen?'&chosen_date='+encodeURIComponent(chosen):''));value.occurrence_id=delivery.current_occurrence_id;if(!value.occurrence_id)throw Error(chosen?'该日期没有未完成的实例，请核对日期。':'当前没有可完成的具体实例，请选择日历日期。');if(!chosen&&!window.confirm('完成 '+delivery.current_occurrence_date+' 的本次计划？'))return;}attempt=prepareAttempt(value,key);}await submitAttempt(attempt);$('notice').textContent=op==='complete'?(t.repeat==='none'?'已完成，历史记录仍保留。':'本次已完成，后续重复计划仍保留。'):'已取消计划。';await refresh();}catch(e){$('notice').textContent=e.message;await refresh().catch(()=>{});}finally{mutationPending=false;render();}}
$('new').onclick=()=>open();$('close').onclick=()=>$('editor').close();$('status').onchange=render;$('day').onchange=render;$('search').oninput=render;
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('selected',x===b));$('day').hidden=view!=='day';render();});
$('form').onsubmit=async event=>{event.preventDefault();if($('save').disabled)return;$('save').disabled=true;try{const changes={title:$('title').value.trim(),body:$('body').value,kind:$('kind').value,repeat:$('repeat').value,due_at:$('due').value?$('due').value+':00+08:00':null,start_at:$('start').value?$('start').value+':00+08:00':null,end_at:$('end').value?$('end').value+':00+08:00':null,remind_at:$('remind-at').value?$('remind-at').value+':00+08:00':null,timezone:'Asia/Shanghai',remind:$('remind').checked,archive_links:Array.from($('archive-links').selectedOptions,option=>option.value)};if((changes.remind||changes.repeat!=='none')&&!(changes.due_at||changes.start_at||changes.remind_at))throw Error('请先选定明确日期和时间。');const payload=editing?{op:'update',task_id:editing.id,changes,expected_revision:editing.revision}:{op:'create',...changes};const t=await submitAttempt(prepareAttempt(payload));$('editor').close();$('notice').textContent='已保存计划。';await refresh();if(t.remind){const d=await api('api/delivery?task_id='+encodeURIComponent(t.id));$('notice').textContent=d.device_scheduled?'已保存，并已同步到设备。':'已保存，等待设备确认提醒。';}}catch(e){$('form-error').textContent=e.message;}finally{$('save').disabled=false;}};
(async()=>{try{csrf=(await api('api/session')).csrf;await refresh();setInterval(()=>{if(!$('editor').open)refresh().catch(()=>{});},15000);}catch(e){$('notice').textContent='暂时无法连接计划服务：'+e.message;}})();
